import React from "react";
import BigBangImage from "./bigBang.png";

function Section2() {
  const title = (
    <h1 className=" text-yellow-500 relative text-2xl font-poppins">
      Formation and Early Evolution
    </h1>
  );

  const body = (
<p className=" text-white font-poppin">
              The solar system was born about 4.6 billion years ago from a
              massive cloud of gas and dust, known as the solar nebula, which
              collapsed under its own gravity. This collapse led to the
              formation of a rotating disk, with the Sun forming at its center
              as nuclear fusion ignited. The remaining material in the disk
              gradually coalesced into planetesimals, which grew into planets.
              The inner solar system, where it was too hot for volatile
              compounds to remain solid, formed rocky planets like Earth, while
              the outer regions gave rise to gas giants like Jupiter and Saturn.
              The early solar system was chaotic, with frequent collisions
              shaping planets, forming moons, and creating craters. Over time,
              the solar system stabilized, paving the way for the emergence of
              life on Earth.
            </p>
  );
  return (
    <>
      <div className="  w-full justify-center flex mt-10 ">
        {/* card start */}
        <div className=" w-10/12 md:w-1/6 h-1/2 border  border-white rounded-xl">
          <div className="">
            <img
              src={BigBangImage}
              alt="Big Bang Image"
              className=" rounded-xl "
            />
          </div>
          <div className=" justify-center flex"></div>
          <div className=" p-2">
            
          </div>
        </div>
        {/* card start */}
      </div>
    </>
  );
}

export default Section2;
